    ],
    'counterpoint' => [
        'be-a-round' => ['title' => 'How to sing a round and keep your part', 'description' => 'Start a round and keep your own line as three more voices join two bars apart, on Row, Row, Row Your Boat. Listen to them, never louder. Free, step by step.'],
        'which-voice-moved' => ['title' => 'Ear training: follow two voices at once', 'description' => 'Listen to two voices, one high and one low, and choose which one moved: one holds, both move, or each sings its own tune. Hear them as often as you like.'],
        'be-the-drone' => ['title' => 'Pedal notes: hold a drone under a tune', 'description' => 'Hold one note on "oo" while a tune moves above you, a pedal named after the organ\'s, first on do and then on the so below it. Breathe between holds. Free.'],
        'a-pattern-that-repeats' => ['title' => 'What is an ostinato? Sing a repeating part', 'description' => 'Sing a four-note pattern eight times through under a falling line, an ostinato that keeps itself going once you know it, then hold the last note. Free.'],
        'the-second-voice' => ['title' => 'How to come in second in a round', 'description' => 'Come in two bars after the leader, who is already singing other notes, and keep your own tune through Are You Sleeping. Listen to both, never louder. Free.'],
        'a-round-in-minor' => ['title' => 'Sing a round in a minor key', 'description' => 'Hear a familiar round turn darker in minor, with its mi and la a half step lower, then come in as the third voice and hold your own line. Free, step by step.'],
        'lead-then-follow' => ['title' => 'What is a canon? Lead, then follow', 'description' => 'Learn how a canon can start at any distance or pitch: lead while the guide follows a bar later an octave down, then follow it yourself. Free, step by step.'],
        'call-and-response' => ['title' => 'Call and response singing: answer home', 'description' => 'The guide sings a call that ends away from do, and you answer with a different phrase that brings it home. A form rooted in West African singing. Free.'],
        'a-slow-line-under-a-tune' => ['title' => 'Countermelody: a slow line under a tune', 'description' => 'Sing four long notes, do, ti, la, so, falling while the tune above turns, each starting a third or a sixth from it, under Ode to Joy. Free, in short steps.'],
        'float-above-it' => ['title' => 'How to sing a descant above the melody', 'description' => 'Float a light descant in long notes on "ah" above O Come, All Ye Faithful and its chords, so the tune still comes through. Light, never loud. Free to sing.'],
        'two-songs-at-once' => ['title' => 'Partner songs: sing two tunes at once', 'description' => 'Learn why songs on the same chords often fit, a quodlibet, then sing Row, Row, Row Your Boat while the guide sings Are You Sleeping. Free, step by step.'],
        'smooth-and-rubbing' => ['title' => 'Consonance and dissonance: smooth or rub', 'description' => 'Hear which intervals sound smooth and which rub, then sing thirds, fifths, sixths and octaves over a drone, and a rub that steps home. Free, in short steps.'],
        'ways-to-move' => ['title' => 'Contrary, similar and oblique motion', 'description' => 'Hear two voices move the same way, opposite ways, or one holding while the other moves, choose which you heard, then sing eight notes against the guide. Free.'],
        'first-species' => ['title' => 'First species counterpoint, sung', 'description' => 'Sing note against note over a cantus, as Fux taught in 1725: begin and end on an octave, use only smooth intervals, and move by step against it. Free.'],
        'two-against-one' => ['title' => 'Second species counterpoint: passing notes', 'description' => 'Sing two notes to each cantus note: the first smooth, the second smooth or a passing note stepping between smooth ones, ending la, ti, do. Free, step by step.'],
        'your-choice' => ['title' => 'Improvise counterpoint against a cantus', 'description' => 'At each cantus note every smooth note in your range lights up: choose one and make your own line, moving against it and avoiding parallel fifths. Free to try.'],
        'hold-on-then-let-go' => ['title' => 'Suspensions: hold a note, then resolve', 'description' => 'Hold do while the bass moves under you, feel it rub against the new chord, then step down to ti and home: a suspension, one of the oldest pulls. Free to sing.'],
    ],
    'improvising-harmony' => [
        'a-part-above' => ['title' => 'How to sing harmony above a melody', 'description' => 'Sing the simplest harmony, a third above the tune, going one note higher where it clashes with the chord, while the guide sings the melody. Free to try.'],
        'major-and-minor-thirds' => ['title' => 'Harmony in thirds: major and minor', 'description' => 'Learn why a third above switches between major and minor to stay in the key, and follow the scale two notes up over the chords instead of counting. Free.'],
        'third-or-fourth' => ['title' => 'When a harmony part goes up to a fourth', 'description' => 'Hear why the third above so rubs against the home chord and do rings instead, then sing the part above with do over every so. Free, in short sung steps.'],
        'harmony-or-the-tune' => ['title' => 'Hear harmony vs melody, then sing by ear', 'description' => 'Learn to tell a harmony that makes chords with the tune from a copy that doubles it, then keep your part above going by ear as the lights fade. Free.'],
        'a-part-below' => ['title' => 'How to sing a harmony below the melody', 'description' => 'Turn a third above into a sixth below: sing the part under the tune, the same notes an octave down, with do under every so, as the guide sings above. Free.'],
        'hold-then-step-off' => ['title' => 'Lost in a harmony? Hold, then step', 'description' => 'When you\'re lost, hold your note until it rubs against the chord, then step, most often down, and come home when the chord does. A trick for any part. Free.'],
        'answer-in-harmony' => ['title' => 'Harmonise a tune after one hearing', 'description' => 'Hear a line once, then sing a part above it as it comes round again: the first step to harmonising a tune you\'ve never heard. Free, in short steps.'],
        'sing-the-chord' => ['title' => 'Harmony from chord tones: sing the triad', 'description' => 'Any note of a triad except the tune\'s own is a harmony. Sing each chord\'s three notes up and back, then choose one long note to each chord. Free to sing.'],
        'close-then-against' => ['title' => 'Two ways to improvise a harmony part', 'description' => 'Make a part your own two ways: barely move, holding or taking the nearest chord note, then move against the tune, falling as it climbs. Compare them. Free.'],
        'lights-when-you-need-them' => ['title' => 'Harmonise by ear, with hints only if lost', 'description' => 'Find each harmony note by ear first: a hint lights only once you\'ve been off a note for a beat, over a spiritual\'s verse and its chords. Free, step by step.'],
        'lights-off' => ['title' => 'Improvise a harmony by ear, no help', 'description' => 'No lights at all: let the chords tell you where you are, sing any chord note except the tune\'s own, and hold until it rubs if you get lost. Free to try.'],
        'the-tenor-above' => ['title' => 'Bluegrass high tenor harmony, by ear', 'description' => 'Sing a tenor part above the lead, part of the high lonesome sound of bluegrass, by ear over Simple Gifts. Light and easy, never pushed. Free, in short steps.'],
    ],
    'barbershop' => [
        'a-chord-that-rings' => ['title' => 'How to ring a barbershop chord', 'description' => 'Hear a chord ring when every voice is tuned to the others, then hold its top note, mi, straight over three voices until it hums. Headphones on. Free.'],
        'straight-not-squeezed' => ['title' => 'Straight tone for barbershop harmony', 'description' => 'Hold your note over a chord with a straight tone, no wave, light and medium-soft, and hear how a wave blurs the ring. Then compare "oo" and "ah". Free.'],
        'whos-out' => ['title' => 'Ear training: find the voice out of tune', 'description' => 'Hear how one voice slightly out of tune makes a whole chord beat, then pick which of the four parts it is: bass, baritone, lead or tenor. Free, by ear.'],
        'octave-and-fifth' => ['title' => 'Tune a chord from the bass: octave, fifth', 'description' => 'Build a chord from its floor: hold the octave over a low do, then the fifth, listening for the moment the shimmer stops and it rings. Free, step by step.'],
        'the-hunt' => ['title' => 'Tuning a third by ear: slide till it rings', 'description' => 'Start on the piano\'s third inside the chord and slide down slowly, a hair at a time, until the beating stops and the chord hums. Headphones on. Free to sing.'],
        'the-barbershop-seventh' => ['title' => 'The barbershop seventh chord: tune it low', 'description' => 'Hear the chord at the heart of barbershop, then hold its seventh on top of three guide voices, lower than you\'d think, until it rings. Free, in short steps.'],
        'the-lead' => ['title' => 'Barbershop lead part: sing the melody', 'description' => 'Sing the lead, the tune the others tune to, on Down by the Old Mill Stream, first with the guide, then with the other three parts. Headphones on. Free.'],
        'the-bass' => ['title' => 'Barbershop bass part: roots and fifths', 'description' => 'Sing the bass, the floor of the chord, in roots and fifths, easy and full with your chin level, never pushed down for depth, under the other three. Free.'],
        'the-tenor' => ['title' => 'Barbershop tenor part: light, above the lead', 'description' => 'Sing the tenor, which floats above the lead, light and soft, the quietest part, with the other three parts and the balance that helps a chord ring. Free.'],
        'the-baritone' => ['title' => 'Barbershop baritone part: the missing note', 'description' => 'Sing the baritone, the note the chord still needs, crossing above the lead on the pickup and under it after. Listen to the chord, not the tune. Free.'],
        'the-swipe' => ['title' => 'What is a barbershop swipe? Sing one', 'description' => 'Sing a swipe as the baritone: your note moves chord by chord on one held word, up a third and down by half steps, each settling where it rings. Free to sing.'],
        'the-post' => ['title' => 'Barbershop post: hold one note as chords move', 'description' => 'Hold your note at the top of the chord while four chords move around it and your note\'s job changes, breathing quickly mid-chord. Headphones on. Free.'],
        'stack-the-tag' => ['title' => 'Record a barbershop tag in four parts', 'description' => 'Record the lead of a short original tag over three guide parts, then the baritone under your own lead, layering your voice as the app was made for. Free.'],
    ],
    'a-cappella-bass' => [
        'under-the-group' => ['title' => 'How to sing a cappella bass: the root', 'description' => 'The bass sings each chord\'s root, the floor the group stands on. Sing four roots on "doo" under three voices, low and easy, never pressed. Free, step by step.'],
        'low-and-easy' => ['title' => 'How to sing low notes without pushing', 'description' => 'Step down from do to fa and back, holding only do, and let low notes come from ease, quieter than your middle notes, with your throat where you speak. Free.'],
        'bright-or-dark' => ['title' => 'How a bass note makes a chord bright or dark', 'description' => 'Hear the same top notes make a bright chord or a dark one depending on the bass, choose by ear, then hold the root that makes it dark. Free, in short steps.'],
        'doom' => ['title' => 'A cappella bass syllables: doom', 'description' => 'Sing "doom", a "doo" closing to a hum, on each root for two beats, then stop the hum right on the beat and rest. A bass note is only as good as its stop.'],
        'dm-dm' => ['title' => 'Bass drum sound for a cappella: dm', 'description' => 'Make the bass\'s drum, "dm": a light tongue tap, then a short hum with lips closed and teeth apart, on every beat, then three to each chord\'s root. Free.'],
        'call-and-response' => ['title' => 'Bass call and response: echo a bar', 'description' => 'The guide sings a bar and you sing it straight back on the same root, on "buh": lips just touching, no puff of air. Three calls to answer. Free, step by step.'],
        'root-and-fifth' => ['title' => 'Bass lines: root and fifth', 'description' => 'Sing the most common bass move: each chord\'s root, then its fifth, and back, the fifth going up on low chords so you never sing too low. Free, step by step.'],
        'keep-the-time' => ['title' => 'Keep time as the a cappella bass', 'description' => 'Hold a steady root-and-fifth groove under the group, keep going alone when they stop in bar three, and be right where they expect when they come back. Free.'],
        'steady-or-rushing' => ['title' => 'Don\'t rush: keep a steady bass groove', 'description' => 'Hear how a bass that rushes pulls a whole group forward, pick the groove that leaned ahead, then sing yours steady as a clock. Free, in short steps you sing.'],
        'walk-down' => ['title' => 'Walking bass line: step down and back', 'description' => 'Walk a bass line down by step from do to fa and back up, one step a beat, landing on each chord as it changes. Listen first, then walk. Free to sing.'],
        'arrive-home' => ['title' => 'How a bass line brings a song home', 'description' => 'Land the last note on do right on the downbeat, arriving from a half step below, a step above, and the leap from so. Three arrivals to sing. Free to practise.'],
        'swing-low-rehearsed' => ['title' => 'Sing the bass of a spiritual under a group', 'description' => 'Sing the roots of Swing Low, Sweet Chariot on "oo", long and steady, under three voices, so the tune floats over you. A real song, with the guide first. Free.'],
    ],
    'gospel-runs' => [
        'five-stairs' => ['title' => 'How to sing gospel runs: start slow', 'description' => 'A run is a few clean notes on one syllable, like stairs. Hum one slowly, then sing it on "A-men", landing on do as the chord comes home. Light, and free.'],
        'five-notes-only' => ['title' => 'The pentatonic scale for vocal runs', 'description' => 'Learn the five notes runs are built from, do, re, mi, so and la, with no fa or ti, pick the run that kept to them, then sing them up and down. Free to sing.'],
        'a-turn' => ['title' => 'Vocal turns: the smallest run', 'description' => 'Sing a turn, the smallest run: the note above, the note, the note below, then the note, around do and around so. Listen, then echo. Free, in a short lesson.'],
        'in-groups' => ['title' => 'Fast vocal runs: sing in groups of three', 'description' => 'Break a fast run into groups of three, leaning a little on the first of each, lighter rather than louder, then hear yours beside the guide\'s. Free to try.'],
        'clean-smeared-or-choppy' => ['title' => 'How to sing clean runs, not smeared', 'description' => 'Hear a clean run, a smeared one that slides and a choppy one with breathy gaps, pick which is which, then sing yours clean: separate and joined. Free.'],
        'where-a-run-goes' => ['title' => 'Where to put a run in a song', 'description' => 'One run a line, on a held word, usually at its end: the tune comes first. Hear where a run fits, then sing a line with one run on its held word. Free.'],
        'bend-up' => ['title' => 'Blue notes: bend up into the third', 'description' => 'Start on the blue note between the piano\'s keys, loose, and bend up slowly into the third, then hold it. The arrival is what matters. Free, light and easy.'],
        'run-up-to-it' => ['title' => 'Rising vocal runs into a held note', 'description' => 'Climb into a note with a run: three light, clean stairs up, then hold the note you ran to, with no pushing at the top. Three rising runs. Free to sing.'],
        'bend-or-stall' => ['title' => 'Hear a bend that lands, then sing one', 'description' => 'A bend has to arrive. Hear which bend lands on the third and which one stalls, then sing your own bend and hold it there. Free, in short steps you sing.'],
        'the-ladder' => ['title' => 'How to sing runs faster, cleanly', 'description' => 'Sing the same run at two, three, then four notes a second, every note still clean, then hear the real speed beside yours. Clean first, then quick. Free.'],
        'swing-low-with-a-run' => ['title' => 'Add a run to a spiritual\'s line', 'description' => 'Sing a line of Swing Low, Sweet Chariot plain, then with a turn on "home", a run that serves the word, and breathe before the next line. Free, step by step.'],
        'steal-away' => ['title' => 'A gentle run in a quiet spiritual', 'description' => 'Sing a line of Steal Away plain, then with one gentle run on a held word, at a medium volume or less, so the word comes first. Free, in a short lesson.'],
    ],
    'scat' => [
        'trade-with-the-band' => ['title' => 'Scat singing for beginners: trade calls', 'description' => 'Scat is singing like a horn, on syllables. The band plays a call and you echo it, ending on any lit note that sounds at rest. No wrong notes here. Free.'],
        'long-short' => ['title' => 'Swing rhythm for singers: long, short', 'description' => 'Hear swing as long, short, "doo-BAH", with a soft d on the long note and a little breath accent on the short one, then sing it on one note and two. Free.'],
        'start-on-the-and' => ['title' => 'Scat phrases that start on the off-beat', 'description' => 'Let the beat go by and start each line just after it, on the "and", the way jazz lines love to, ending clean on the t of "dat". Echo four calls. Free.'],
        'the-twelve-bars' => ['title' => 'The 12-bar blues for singers', 'description' => 'Learn the twelve-bar blues, four bars home, two away and back, then the turnaround, and sing each bar\'s root with a swung "doo-bah" into each change. Free.'],
        'finish-the-phrase' => ['title' => 'Finish a jazz phrase on a chord tone', 'description' => 'The band plays a phrase and stops short, and you sing its last note: any of the chord\'s 1, 3 or 5. Four phrases, then hear yours beside the guide\'s. Free.'],
        'the-colour-note' => ['title' => 'Land on the third: the chord\'s colour note', 'description' => 'Hear the third as the note that makes a chord sound major, then echo four calls, each landing right on the chord\'s third with no slide. Free, in short steps.'],
        'keep-the-rhythm-change-the-end' => ['title' => 'Start improvising: change a phrase\'s end', 'description' => 'Echo the call\'s rhythm exactly and choose its last two notes yourself, from any of the chord\'s tones, the flat seven too. Your first small improvising. Free.'],
        'answer-the-call' => ['title' => 'Improvise a scat answer to a call', 'description' => 'Keep the call\'s rhythm and syllables and pick every note of your answer from the chord\'s tones, then hear yours beside the guide\'s. Four calls to answer.'],
        'a-riff' => ['title' => 'Sing a blues riff over the changes', 'description' => 'Sing a riff, a short phrase repeated over the changes, built on the minor pentatonic and ending on five so it fits every chord of the blues. Free to sing.'],
        'the-blue-note' => ['title' => 'The blue note for singers: rub, then lift', 'description' => 'Sing the flat third against a major chord so it rubs on purpose, then lift to the third, four times over the chord, with no pushing on the bend. Free to try.'],
        'the-blues-scale' => ['title' => 'How to sing the blues scale', 'description' => 'Add the flat five to the riff\'s five notes to make the six-note blues scale, then sing it up and down, swung, on "bee-dah". Free, in a short sung lesson.'],
        'four-bars-of-your-own' => ['title' => 'Your first scat solo: four bars', 'description' => 'Sing four bars over a blues chord, a rhythm written for you and every note your choice from the blues scale, ending on a chord tone. Everything lit fits.'],
    ],
    'folk-and-early-music' => [
        'join-the-crew' => ['title' => 'How to sing a sea shanty as the crew', 'description' => 'Learn how sailors sang shanties to pull together, then answer each line of Drunken Sailor as the crew, strong not loud, over a bagpipe-like drone. Free.'],
        'ring-with-the-drone' => ['title' => 'Sing in tune with a drone: a plain folk tone', 'description' => 'Hear a slightly out-of-tune note wobble against a drone, slide up until the wobble goes, then hold the note plain and easy so the two ring as one. Free.'],
        'tell-it' => ['title' => 'How to sing a folk ballad: tell the story', 'description' => 'Sing a ballad as a story, each word given its own time and the long words lasting, on Barbara Allen over a drone, plain and clear. Free, line by line.'],
        'the-bright-note' => ['title' => 'The Dorian mode: hear and sing it', 'description' => 'Hear the bright note that makes an old tune sound old, a minor scale with its sixth raised, then sing the Dorian scale and a line both ways. Free to sing.'],
        'the-soft-note' => ['title' => 'The Mixolydian mode: hear and sing it', 'description' => 'Hear the soft seventh of the Mixolydian mode, a major scale with one note lower, then sing its scale and the chorus of Old Joe Clark over a drone. Free.'],
        'name-that-mode' => ['title' => 'Dorian or Mixolydian? Tell modes by ear', 'description' => 'Sing the Dorian and Mixolydian scales over the same drone, then hear two short tunes and pick each one\'s mode by its bright or soft note. Free, step by step.'],
        'a-flick-from-above' => ['title' => 'Folk singing ornaments: the flick', 'description' => 'Decorate a note with a flick, a quick touch of the next note up, light from the breath and never the jaw, starting slow and getting a touch quicker. Free.'],
        'the-turn' => ['title' => 'Folk singing ornaments: the turn', 'description' => 'Wrap a turn around a long note: the note above, the note, the note below and back, small and light, sung slowly first, then a touch quicker. Free to sing.'],
        'spot-the-ornament' => ['title' => 'Hear folk ornaments: spot the flick', 'description' => 'A good ornament is small. Sing a line with a flick, then listen to another and pick the word that carries a flick or a turn. Ear training for folk. Free.'],
        'where-do-re-mi-come-from' => ['title' => 'Where do re mi come from? Sing the hymn', 'description' => 'Learn how Guido of Arezzo named the notes about a thousand years ago from a hymn whose lines each start a note higher, then sing ut, re, mi up and down. Free.'],
        'lining-out' => ['title' => 'Lining out: how congregations sang hymns', 'description' => 'Learn lining out, where a leader sang each line and everyone sang it back, then answer the lines of Wondrous Love, a shape-note hymn, with no drone. Free.'],
        'on-your-own' => ['title' => 'Sing unaccompanied and stay in key', 'description' => 'Sing a ballad line over a drone, then as the drone fades, then a whole verse alone, and hear the home note at the end to find out if you stayed in key. Free.'],
    ],
    'yodeling' => [
        'find-the-flip' => ['title' => 'How to yodel: find your flip', 'description' => 'Find where your voice flips with quiet sirens, check it in the same spot twice, then jump over it on purpose into your first "yo-hee-o". Light, never a crack.'],
        'two-voices' => ['title' => 'Chest voice and head voice for yodeling', 'description' => 'Hear your voice\'s two sounds, chest voice low and speech-like and head voice high and hooty, then hold a "ho" below your flip and a "hoo" above it. Free.'],
        'flip-or-slide' => ['title' => 'Yodel flip or slide? Hear the difference', 'description' => 'Hear how a yodel jumps straight from one note to the other while a slide passes through every note between, then pick which is which by ear. Free and short.'],
        'open-below-narrow-above' => ['title' => 'Yodel vowels: yo low, hee high', 'description' => 'Switch vowel at the flip, an open "yo" on the low chest note and a narrow "hee" on the high head note, to help the voice tip over, then sing hooks in time.'],
        'the-way-down' => ['title' => 'How to yodel down without slamming', 'description' => 'Flip down from head voice into chest voice lightly, at speaking volume, as if you\'d just said "oh", over an octave and then a fifth. Never a thump. Free.'],
        'sixths-octaves-fifths' => ['title' => 'Yodel leaps: sixths, octaves and fifths', 'description' => 'Flip across a sixth, an octave and a fifth, the smallest and hardest, without sliding, then sing all three in a row. Rest first if you\'ve flipped a lot. Free.'],
        'on-the-chord' => ['title' => 'Yodeling over chords: move with them', 'description' => 'Hear why a yodel sounds right when both its notes belong to the chord, then sing hooks whose top note moves up a half step as the chord changes. Free.'],
        'a-cowboy-lope' => ['title' => 'How to yodel like a cowboy: the lope', 'description' => 'Sing the cowboy yodel\'s sway, long, short, long, like a horse\'s easy lope, keeping the quick top note flipping cleanly, four in a row over chords. Free.'],
        'which-one-fits' => ['title' => 'Hear whether a yodel fits the chord', 'description' => 'Over a chord, a yodel\'s top note either belongs or rubs. Listen to two, pick the one that fits, and train your ear before you sing it. Free, a short lesson.'],
        'the-roll' => ['title' => 'How to do a yodel roll', 'description' => 'Sing a roll, several flips on one breath: low, high, low, high, low, slowly first so each flip is clean, never more than four to a breath. Free, step by step.'],
        'slow-to-quicker' => ['title' => 'Faster yodeling: a roll at three speeds', 'description' => 'Sing the same roll at 60, 76 and 92 beats a minute, keeping every flip clean, and stay at the speed before if they start to smear. Free, in short steps.'],
        'clean-or-smeared' => ['title' => 'Clean yodel or smeared? Train your ear', 'description' => 'Hear a fast roll that flips cleanly beside one that smears into slides like a siren, and pick the clean one. The ear behind a sparkling yodel. Free and short.'],
    ],
    'pop-and-country' => [
        'plain-to-styled' => ['title' => 'How to style a melody: plain to styled', 'description' => 'A plain tune and a styled one are the same notes. Sing a traditional line plain, then again with a small scoop into one word. Light, at medium volume. Free.'],
        'the-scoop' => ['title' => 'How to scoop into a note on purpose', 'description' => 'Slide up into a note from a little below so it sounds meant, not missed, then sing quick scoops and slow, lazy ones, landing and holding each note. Free.'],
        'the-fall-off' => ['title' => 'How to sing a fall-off at a note\'s end', 'description' => 'Hold a note, then let its end drop away, letting the pitch go while the breath stays steady, never collapsing into a creak. Short, then longer notes. Free.'],
        'the-slide' => ['title' => 'Vocal slides: glide from note to note', 'description' => 'Glide from one note to the next on one breath through every pitch between, up a third and back, then a fifth, then in a line with two slides. Free to sing.'],
        'the-little-cry' => ['title' => 'The country cry: a tiny vocal flip', 'description' => 'Add the little cry country singers use, a quick flip up into the lighter voice and straight back, light and never a hard catch, slow first, then in a song.'],
        'which-move' => ['title' => 'Hear vocal styling: scoop, fall, slide, cry', 'description' => 'Hear a line with one move each round and pick it: a scoop, a fall-off, a slide or a cry. Then decide which one was overdone. Ear training for style. Free.'],
        'three-colours' => ['title' => 'Breathy, bright or twangy: vocal tone colour', 'description' => 'Sing the same line three ways, breathy, bright and with a little twang, and hear each beside the guide\'s. You\'re the judge of the tone. Free, never pressed.'],
        'the-crooner' => ['title' => 'How to croon: quiet, close singing', 'description' => 'Croon like the singers of the early microphone age, quiet and close with a little air and fall-offs at line ends, on Aura Lee from 1861. Never a whisper.'],
        'the-country-edge' => ['title' => 'How to sing with country twang', 'description' => 'Find a little twang from a light, bratty "nyeh", check it isn\'t just nasal with a nose pinch, then sing a line with twang and a light cry. Never squeezed.'],
        'where-the-moves-go' => ['title' => 'Where to add style to a song\'s melody', 'description' => 'A rule of thumb: put moves on long notes and the ends of lines and stay plain elsewhere, so they mean more. Then style a line with two moves at most. Free.'],
        'answer-back' => ['title' => 'Style a melody your own way: answer back', 'description' => 'The guide styles a line its way, and you answer the same notes with moves of your own: two or three, on the long notes. Less is more. Free, line by line.'],
        'your-way' => ['title' => 'Put your own style on a classic melody', 'description' => 'Style a line of Beautiful Dreamer your way, with a scoop, a fall-off, a slide or a cry, then sing it plain to hear the difference, and once more. Free.'],
    ],
    'musical-theatre' => [
        'say-it-then-sing-it' => ['title' => 'Musical theatre singing: say it, then sing', 'description' => 'Speak a line in rhythm as the character would, then sing the same words on the notes, keeping it sounding like you talking. A Gilbert and Sullivan start.'],
        'the-word-that-matters' => ['title' => 'How to stress the right word in a song', 'description' => 'Find the one word in each line that matters most, see how the music puts it on a strong beat, the ONE of a waltz, then sing a line leaning on it. Free.'],
        'breathe-where-the-thought-ends' => ['title' => 'Breathe with the thought: phrasing a song', 'description' => 'Breathe at the end of a thought, not at every comma, so the sense stays whole. Hear the difference, then sing three lines breathing only where they end. Free.'],
        'two-notes-many-words' => ['title' => 'Patter songs: many words on two notes', 'description' => 'Learn patter, lots of words on two neighbouring notes, as the Major-General sings it: one word a beat, slowly, echoing the guide a bar at a time. Free.'],
        'consonant-first' => ['title' => 'Clear words in patter: consonant first', 'description' => 'Put each consonant a hair before the beat so the vowel lands on it, the part the audience hears, with a loose jaw, then play it back with the words shown.'],
        'a-little-quicker' => ['title' => 'How to sing patter faster and clearly', 'description' => 'Clear first, then quicker: sing a patter line slowly, hear which take rushed, then sing it evenly at three words a second, about half the real speed. Free.'],
        'bright-like-talking' => ['title' => 'Bright musical theatre sound, like talking', 'description' => 'Say a line as if calling a friend across a room, at speaking volume, then sing it that way near your comfortable note. Bright, not belt, never pushed. Free.'],
        'tall-and-steady' => ['title' => 'Legit singing: tall vowels, held notes', 'description' => 'Learn the classic legit sound: tall vowels with space inside, long notes held to their full value, and "why" kept on "ah" until the very end. Free to sing.'],
        'hold-the-first-vowel' => ['title' => 'Diphthongs in musical theatre singing', 'description' => 'Why, I, my and day are each two vowels: hold the first for the whole note and give the second only at the very end, kept true in the middle of your voice.'],
        'the-button' => ['title' => 'The button: how to end a song', 'description' => 'End a song with a button: hold its last note to its full value, stop exactly on the beat, then stay still while the thought lands. A short lesson, free.'],
        'sing-it-to-someone' => ['title' => 'Sing to someone: acting a song', 'description' => 'Picture a friend at the very back of the gallery and sing the line to them, clearer and meant rather than louder: an old actor\'s tip. Then play it back. Free.'],
        'hail-poetry-the-first-half' => ['title' => 'Sing the tune in an unaccompanied chorus', 'description' => 'Sing the tune of a Gilbert and Sullivan chorus marked "voices only", phrase by phrase with the company around you, from The Pirates of Penzance. Free.'],
    ],
    'learn-your-choir-part' => [
        'your-line-in-the-sound' => ['title' => 'How to hear your part in a choir', 'description' => 'Hear your line inside all four parts, find your first note in the pianist\'s chord, follow it on the page, then sing two lines without the guide. Free.'],
        'fix-the-hard-bars' => ['title' => 'How to learn the hard bars of a choir part', 'description' => 'Learn two new lines a little slower, find what makes a bar hard, then sing it slow and clean and bring it up to speed until the verse holds. Free.'],
        'guide-on-guide-off' => ['title' => 'Learn your choir part without the guide', 'description' => 'Learn the refrain and the last line, put the guide down early, then sing your whole part on your own with the other parts. Free, step by step, at home.'],
        'ready-for-rehearsal' => ['title' => 'How to prepare for a choir rehearsal', 'description' => 'One run-through the night before, a gentle hum in the morning, then a run that never stops and a dress rehearsal you record, so you walk in ready. Free.'],
    ],
    'live-looping' => [
        'the-loop' => ['title' => 'Live looping for singers: your first loop', 'description' => 'Sing a two-bar bass on "doom", let it loop, then fill its gaps with a second part: a band made of one voice. Headphones on, easy volume. Free, step by step.'],
        'lock-to-yourself' => ['title' => 'Live looping: drop out and come back in', 'description' => 'Sing the bass, fill its gaps, then rest a round with the loop in your head and come back in right where it expects you. A looper\'s first test. Free to sing.'],
        'a-longer-loop' => ['title' => 'A four-bar vocal loop through four chords', 'description' => 'Build a four-bar bass, do, low la, re, low so, each note twice, the last stopped early for your breath, then record your first loop, kept for later. Free.'],
        'the-pad' => ['title' => 'Vocal looping: add a soft pad over the bass', 'description' => 'Over your looping bass, hold a soft "oo" on mi, then re: a pad, felt more than heard, each layer on its own sound so you can hear them all. Free to sing.'],
        'a-rhythm-part' => ['title' => 'A vocal rhythm part: short and bright', 'description' => 'Add a rhythm part to your loop: two quick, bright "doo-doo"s on so in the bass\'s gaps, more like a drum than a tune, after choosing the one that fits. Free.'],
        'three-layers' => ['title' => 'Stack three vocal layers on a loop', 'description' => 'Stack the four-bar loop three layers deep, a bass, a soft pad and a rhythm part, then sing all three from memory with nothing lit, as on stage. Free to sing.'],
        'row-row-row-your-boat' => ['title' => 'Loop a one-note bass under a simple tune', 'description' => 'A tune on one chord needs a loop of just one note: sing it low on "doom", then Row, Row, Row Your Boat over it, rocking two beats a bar. Free, step by step.'],
        'are-you-sleeping-frere-jacques' => ['title' => 'Loop a round\'s last line as its own bass', 'description' => 'Loop the round\'s last line, "ding, dang, dong", as its own bass, add a soft pad on so, then sing Frère Jacques over every bar of it. Free, step by step.'],
        'drunken-sailor' => ['title' => 'Loop an eight-bar bass under a sea shanty', 'description' => 'Loop a whole eight-bar verse for Drunken Sailor, home on low la since it\'s minor, sing the tune on top, then a round with yourself over a looped bass. Free.'],
        'choose-your-bass' => ['title' => 'Make up your own bass line for a loop', 'description' => 'Choose your own bass for Drunken Sailor as you go: two notes light in every bar, either one fits, as each is a note of that bar\'s chord. Free, step by step.'],
        'choose-your-layers' => ['title' => 'Your own loop: choose bass and pad by ear', 'description' => 'Pick your own bass and pad by ear, either lit note fits each bar, then sing Drunken Sailor\'s tune over your layers, kept as a song in Sing. Free.'],
    ],
    'backing-vocals' => [
        'a-pad' => ['title' => 'Backing vocals: how to sing a soft pad', 'description' => 'Hold one soft "oo" under the tune, do, then ti when the chord moves, staying still while the tune passes over it, softer than the lead. Free, step by step.'],
        'moving-with-the-chords' => ['title' => 'Backing vocal parts that follow the chords', 'description' => 'Move your pad only when you must: keep the note the new chord shares, else step to the nearest one, and learn why an "oo" blends better. Free to sing.'],
        'together-off' => ['title' => 'Backing vocals: stop and breathe together', 'description' => 'Stop when the tune\'s phrase ends and come back in together, each pad note the one the phrase\'s chords share, then a slow, low pad under a folk song. Free.'],
        'doo-wah' => ['title' => 'How to sing doo-wop backing: doo-wah', 'description' => 'Sing "doo" on the beat and open to "wah" over a four-chord loop, one note a chord, light and never punched, the change all in the vowel. Free, step by step.'],
        'shoo-bop' => ['title' => 'Doo-wop backing rhythm: short, light bops', 'description' => 'Sing short, light "bop"s on beats two and four, in the gaps of the chords, choosing each pair by ear, and never pushing a low bop. Free, in short steps.'],
        'three-parts' => ['title' => 'Stack three-part backing vocals yourself', 'description' => 'Build a low, middle and top part over your own takes, each a step from its last note, then sing them with rhythm under a lead, kept as a song. Free to sing.'],
        'fill-the-gap' => ['title' => 'Backing vocals: fill the gaps in the lead', 'description' => 'Wait for the tune\'s long note, then fill it with a short, soft "oo" underneath, small enough never to cover the lead, choosing each answer by ear. Free.'],
        'the-response' => ['title' => 'Call and response: sing the answer part', 'description' => 'Sing the oldest backing job: the leader calls each line of a folk song and you answer "Hallelujah", resting through the next call, never shouting. Free.'],
        'back-in-on-time' => ['title' => 'Backing vocals: come back in on the beat', 'description' => 'Echo the tune, count the gap while it rests, then answer right on the beat, light and quick, through a whole verse and chorus of call and response. Free.'],
        'home-on-the-range-a-pad-then-answers' => ['title' => 'Backing a real song: a pad, then answers', 'description' => 'Hold a soft pad for two lines of a cowboy song, then switch to answers, waiting, echoing the tune and filling its gaps, after hearing the tune first. Free.'],
        'amazing-grace-two-more-parts' => ['title' => 'Three-part backing vocals under a hymn', 'description' => 'Add a middle and a top part above your pad from lesson 1, breathing at different times so the sound never stops, then all three kept as a song. Free to sing.'],
    ],
    'sea-shanties-and-work-songs' => [
        'the-answer' => ['title' => 'How to sing a sea shanty: answer the call', 'description' => 'Sing the crew\'s answer to the shantyman, on pitch and all together, as big as you could keep up for a whole song, then the whole chorus. Free, step by step.'],
        'sweating-up' => ['title' => 'Sweating up: one short answer, one pull', 'description' => 'Learn a short-pull shanty: one quick answer and one strong pull at the end, used to get the last inch out of a rope, sung, not shouted. Free to sing.'],
        'breathe-in-the-call' => ['title' => 'Shanty breathing: breathe in the call', 'description' => 'Take a low, quiet breath while the shantyman sings, then one breath for each answer, through a long hoist and a whole song sung as the crew. Free to sing.'],
        'on-the-pull' => ['title' => 'Shanty rhythm: land the answer on the beat', 'description' => 'Put each answer on the beat, as a crew had to so the rope moved: the vowel on the beat, not the h, and one strong pull, sung and short. Free, in short steps.'],
        'stamp-and-go' => ['title' => 'Stamp and go: the shanty you walk to', 'description' => 'Sing a stamp-and-go chorus on the beat, the beat set by your feet as a crew tramped along the deck with the rope. Walk it if you like. Free, in short steps.'],
        'the-long-hoist' => ['title' => 'Halyard shanties: the long hoist', 'description' => 'Sing a halyard shanty\'s two short answers on the beat at a steady hoist, steady before fast, the way a sail went up, with the shantyman\'s calls between. Free.'],
        'walk-it-round' => ['title' => 'Capstan shanties: walk the bars round', 'description' => 'Sing a capstan shanty with no pull at all, the crew walking the bars round, then two verses of the last song of a voyage, every chorus on the beat. Free.'],
        'lead-the-call' => ['title' => 'Be the shantyman: lead the call', 'description' => 'Sing the shantyman\'s verse alone, a big warm voice that never strains, while a four-part crew answers you with the chorus you already know. Free to sing.'],
        'find-the-call' => ['title' => 'Find the shantyman\'s first note by ear', 'description' => 'Find your call\'s first note from the crew\'s last: they end on home, and your call begins a fifth above it. Then sing the call, a big warm voice. Free.'],
        'make-up-a-line' => ['title' => 'Make up your own shanty verse', 'description' => 'Shantymen made up new lines as they went while the chorus stayed the same: fit a line of your own, one syllable a note, then lead a whole verse. Free to sing.'],
        'all-together' => ['title' => 'Sing a shanty chorus with a four-part crew', 'description' => 'Sing the chorus inside a crew of four parts, your voice in among theirs, hearing the others as you sing and pulling with your body, never your throat. Free.'],
        'a-part-under-the-tune' => ['title' => 'A harmony part under a shanty tune', 'description' => 'Sing a line of your own under the tune, from a 1921 harmony: lower and steadier than the tune, ending with it on home, while the tune goes by above you. Free.'],
        'the-root' => ['title' => 'Sing the root of each chord under a tune', 'description' => 'Hold the root of each chord on a low, easy doom, the note the crew stands on, changing when the chord does, while the tune sings over you. Free, step by step.'],
        'stack-a-crew' => ['title' => 'Stack a crew of your own voice', 'description' => 'Sing your answers, then a part under them over your own first take, then keep your own crew as a song, beside your first answer from lesson 1. Free to sing.'],
    ],
    // Classical singing basics: each lesson page (each unit's challenge folds into the page before it).
    'classical-singing-basics' => [
        'one-joined-line' => ['title' => 'One joined line: legato for beginners', 'description' => 'Hear joined notes beside separate ones, then sing a first Italian phrase on "ah" with no gap between its notes, in your own easy voice. Free.'],
        'a-clean-start' => ['title' => 'A clean start to every note', 'description' => 'Start each note right on its pitch, never sliding up from below or with a click: single notes echoed, then five short starts, each on its note at once. Free.'],
        'one-vowel-many-notes' => ['title' => 'One vowel over many notes', 'description' => 'Carry one vowel through a run of notes in Concone\'s vocalise, then sing Vaccai\'s first lesson, your first Italian song, joined all the way. Free.'],
        'breathe-at-the-comma' => ['title' => 'Breathe at the comma: one breath a phrase', 'description' => 'Find where a phrase lets you breathe: sing Brahms\'s lullaby a phrase at a time, breathing at each comma and coming in on time after it. Free lesson.'],
        'steady-in-the-middle' => ['title' => 'Hold a long note steady, without a sag', 'description' => 'Hold a long note in the middle of your voice, steady to its end with no sag in pitch; let a gentle wave in only if it comes by itself. Free lesson.'],
        'the-end-of-a-phrase' => ['title' => 'End a phrase on time, not early', 'description' => 'End a phrase on purpose: Concone\'s last bars, the long note held and stopped on time, then the first verse of Brahms\'s lullaby, a phrase a breath. Free.'],
        'skips-that-stay-joined' => ['title' => 'Skips that stay joined: legato over leaps', 'description' => 'Keep the line joined when the tune skips a third or more, on Vaccai\'s Italian lessons, so a leap sounds like part of the phrase, never a break. Free.'],
        'the-leaning-note' => ['title' => 'The leaning note: singing an appoggiatura', 'description' => 'Learn the appoggiatura, the leaning note that falls onto the main one, and give it its full value on the beat, as Vaccai taught singers. Free, short steps.'],
        'a-slide-on-purpose' => ['title' => 'A slide on purpose: portamento, not dragging', 'description' => 'Slide between two notes only where the music asks, never dragging, then sing all of Vaccai\'s Semplicetta tortorella in Italian, every skip clean. Free.'],
        'caro-mio-ben-the-opening' => ['title' => 'A song for voice and piano: the opening', 'description' => 'Learn the opening of Caro mio ben, the Italian song for voice and piano, phrase by phrase, with every note joined and a breath at each comma. Free.'],
        'the-middle' => ['title' => 'The middle of an Italian song', 'description' => 'Sing the middle of Caro mio ben, between its opening and its return, keeping every note joined and each phrase on one breath. Free, in short steps.'],
        'the-return-and-the-ending' => ['title' => 'The return and the ending', 'description' => 'Sing the return of the opening and the last phrase of Caro mio ben, then the whole song for voice and piano from start to end, kept as your song. Free.'],
    ],
    // Blues singing: each lesson page (each unit's challenge folds into the page before it).
    'blues-singing' => [
        'say-it-say-it-again' => ['title' => 'Say it, say it again: the blues line', 'description' => 'Learn the blues verse\'s first two lines: sing a line, then the same line again, as blues singers did long before anyone printed it. A free lesson.'],
        'hum-it-first' => ['title' => 'Hum a blues verse first', 'description' => 'Hum the whole verse before you sing a word, so the tune\'s shape and its long notes are in your ear before the words come. A free lesson, in short steps.'],
        'the-answer-line' => ['title' => 'The answer line: how a blues verse ends', 'description' => 'Learn the third line, the one that answers the first two, then sing one whole blues verse, three lines, from first word to last. A free lesson.'],
        'the-blue-note-in-the-tune' => ['title' => 'The blue note in a blues tune', 'description' => 'Find the blue note, the lower, bluer note the tune leans on before the plain one, and sing it where the tune asks for it, on pitch. A free lesson.'],
        'a-bluer-ending' => ['title' => 'A bluer ending to a blues line', 'description' => 'End a line on a bluer note than the plain one, as blues tunes often do, and hear how it changes the feel of the whole line. A free lesson, in short steps.'],
        'not-every-blues-has-three-lines' => ['title' => 'Not every blues has three lines', 'description' => 'Meet a blues verse with a different shape from the three-line one, then sing two passages of a blues printed in Chicago in 1921, blue notes and all. Free.'],
        'leave-room' => ['title' => 'Leave room for the band', 'description' => 'Stop singing where the band takes its turn, then come back in on time after it, the way a blues verse leaves room for the band to answer. A free lesson.'],
        'the-fall' => ['title' => 'The fall at the end of a line', 'description' => 'Let a long note fall away at the end of a line, but only where the song asks for it, and land it so it still sounds on purpose. A free lesson, in short steps.'],
        'lay-back' => ['title' => 'Lay back: singing behind the beat', 'description' => 'Start each line just behind the beat, relaxed on the steady chords, then sing the whole verse of a blues about a train, after each of the band\'s turns. Free.'],
        'your-first-line' => ['title' => 'Your first blues line', 'description' => 'Make up a blues line of your own and sing it to a printed tune: the words are yours, and the app hears only the notes. A free lesson, in short steps.'],
        'your-answer-line' => ['title' => 'Your answer line', 'description' => 'Write the line that answers your first one, so your verse turns the way a blues verse does, and sing both to the tune on pitch. A free lesson, in short steps.'],
        'your-verse' => ['title' => 'Your own blues verse', 'description' => 'Sing your whole verse, three lines of your own, to a tune printed in Chicago in 1924, then keep it as a song beside the printed one. A free lesson.'],
    ],
    // Humming and lip trills: each lesson page (each unit's challenge folds into the page before it).
    'humming-and-lip-trills' => [
        'a-roller-coaster' => ['title' => 'Lip trills for beginners: a roller coaster', 'description' => 'Bubble your lips and ride the ribbon up and down like a roller coaster, on one easy, unbroken sound. The app follows your pitch. A free lesson.'],
        'keep-it-bubbling' => ['title' => 'Keep a lip trill bubbling', 'description' => 'Keep the bubble going longer and steadier on one easy breath. Can\'t trill yet? A hum or an "oo" does the same job here. A free lesson, in short steps.'],
        'trill-on-a-tune' => ['title' => 'A lip trill on a tune', 'description' => 'Carry your lip trill onto a short tune, each note on pitch, then ride the big dipper on one bubble. Quiet to medium and easy, never forced. A free lesson.'],
        'ng' => ['title' => 'The ng sound: a gentle siren', 'description' => 'Sing the "ng" at the end of "sing", then slide it up and down like a quiet siren, on one easy sound that never stops. A free lesson, in short steps.'],
        'bigger-sirens' => ['title' => 'Bigger ng sirens', 'description' => 'Stretch your "ng" siren a little higher and lower, never forcing it, on one easy sound that never stops along the way. A free lesson, in short steps.'],
        'ng-to-ah' => ['title' => 'From ng to ah', 'description' => 'Open your "ng" into a long "ah", keeping the easy sound of the hum, then loop your siren smoothly round and round on one breath. A free lesson.'],
        'a-buzzing-hum' => ['title' => 'A buzzing hum', 'description' => 'Hum on an easy, ringing tone and feel for a gentle buzz on your lips and around your nose, then hold the hum on its note. A free lesson, in short steps.'],
        'hum-a-tune' => ['title' => 'Hum a tune', 'description' => 'Hum a short tune with your mouth closed, each note on pitch and the hum unbroken from the first note to the last. A free lesson, in short steps.'],
        'hum-to-open' => ['title' => 'Open a hum into a vowel', 'description' => 'Open your hum so "m" becomes "ma": "mm" opens into "ah" on one note, then on three notes going up, then a longer line hummed all the way. A free lesson.'],
        'trill-into-a-line' => ['title' => 'From a lip trill into a sung line', 'description' => 'Trill a short line, then sing the same line on "ah", as easy as the trill, so the warm-up carries straight into singing. A free lesson, in short steps.'],
        'hum-into-words' => ['title' => 'Hum into words', 'description' => 'Hum a line first, then sing the same line with its words, keeping the hum\'s easy, ringing sound in every note. A free lesson, in short steps.'],
        'a-three-minute-warm-up' => ['title' => 'A three-minute warm-up', 'description' => 'Lip trills, "ng" sirens and a hum in a three-minute warm-up, then your first roller coaster beside today\'s, and a line sung on a warmed-up voice. Free.'],
    ],
    // Whistling: each lesson page (each unit's challenge folds into the page before it).
    'whistling' => [
        'find-your-whistle' => ['title' => 'How to whistle: find your whistle note', 'description' => 'Find your whistle note with soft lips, an easy jaw and a gentle stream of air. For many people a first whistle takes a few days, and that\'s fine. Free.'],
        'hold-it-steady' => ['title' => 'Hold a whistled note steady', 'description' => 'Hold your whistle note steady on one gentle breath, the app following its pitch, then once more, from beginning to end, lips soft. A free lesson.'],
        'a-clean-start' => ['title' => 'A clean whistle on every note', 'description' => 'Begin each whistled note cleanly, right on its pitch, then whistle Hot Cross Buns, your first whole tune, note by note. A free lesson, in short steps.'],
        'the-next-note-up' => ['title' => 'Whistle the next note up', 'description' => 'Move your whistle to the next note up with your tongue: a silent "ee" to go up, "oo" to come down, each note landed on its pitch. A free lesson.'],
        'five-notes-one-at-a-time' => ['title' => 'Whistle five notes, one at a time', 'description' => 'Whistle five notes in a row, one at a time, each set by your tongue and landed on its pitch before the next one. A free lesson, in short steps.'],
        'a-slide' => ['title' => 'Whistle a smooth slide between notes', 'description' => 'Slide your whistle smoothly from one note to the next and follow the slide on pitch, then whistle the first eight bars of Ode to Joy. A free lesson.'],
        'small-jumps' => ['title' => 'Small jumps when you whistle', 'description' => 'Jump a small way between whistled notes, landing each one cleanly on its pitch rather than sliding into it. Lips soft, air gentle. A free lesson.'],
        'bigger-jumps' => ['title' => 'Bigger jumps when you whistle', 'description' => 'Whistle bigger jumps between notes, landing each one on its pitch, with your tongue doing the work and your lips staying soft. A free lesson.'],
        'the-big-jump' => ['title' => 'The big jump: whistling a sixth', 'description' => 'Whistle the big jump of a sixth, only as high as is easy for you, then whistle the turning line of Simple Gifts, each leap landed. A free lesson.'],
        'in-tune-with-a-held-note' => ['title' => 'Whistle in tune with a held note', 'description' => 'Whistle in tune with a note held under you, hearing when the two agree, so your whistle stays true from one note to the next. A free lesson.'],
        'a-breath-each-phrase' => ['title' => 'A breath for each whistled phrase', 'description' => 'Take one breath for each phrase of a tune and whistle it through on that breath, lips soft and air gentle; light-headed, stop and breathe. Free.'],
        'an-even-wave' => ['title' => 'An even wave in your whistle', 'description' => 'Add an even wave to a long whistled note if you like, never required, then whistle The Water Is Wide whole, with a second whistle under it. Free.'],
    ],
];
